#!/usr/bin/env dotnet
#:property AllowUnsafeBlocks=true

Span<nint> values = stackalloc nint[5];
for (int i = 0; i < values.Length; i++)
    values[i] = (nint)(i * 10);

Console.WriteLine($"Span<nint> length: {values.Length}, sizeof(nint): {nint.Size}");
for (int i = 0; i < values.Length; i++)
    Console.WriteLine($"  [{i}] = {values[i]}");

